-- TEST ONLY: tagged fixtures and all queued messages roll back. Not a migration.
begin;
create function pg_temp.ticket_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end;$$;
create function pg_temp.ticket_denied(statement text) returns boolean language plpgsql as $$begin execute statement;return false;exception when others then return true;end;$$;
insert into auth.users(id,email,aud,role,raw_app_meta_data,raw_user_meta_data,email_confirmed_at)
select ('f0280000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ticket-'||n||'@test.invalid','authenticated','authenticated','{}','{}',now() from generate_series(1,3)n;
update public.profiles set access_status='active',is_test_account=true,visibility_paused=false,display_name='Ticket Tester '||right(id::text,1) where id::text like 'f0280000-%';
insert into public.venues(id,name,city,country,address_line) values('f0281000-0000-4000-8000-000000000001','[TEST] Ticket venue','Nairobi','Kenya','[TEST] Ticket Lane');
insert into public.events(id,slug,title,format,audience,status,starts_at,ends_at,venue_id,created_by)
select ('f0282000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'test-ticket-'||n,'[TEST] Ticket event '||n,'in_person','public','published',now()+interval '1 day',now()+interval '2 days','f0281000-0000-4000-8000-000000000001','f0280000-0000-4000-8000-000000000001' from generate_series(1,2)n;
insert into public.event_hosts(event_id,user_id,status,assigned_by) values('f0282000-0000-4000-8000-000000000001','f0280000-0000-4000-8000-000000000001','active','f0280000-0000-4000-8000-000000000001');
insert into public.ticket_types(id,event_id,name,price_minor,currency,inventory_quantity,status) values('f0284000-0000-4000-8000-000000000001','f0282000-0000-4000-8000-000000000001','[TEST] Free admission',0,'KES',10,'on_sale');
insert into public.orders(id,user_id,event_id,status,processing_mode,currency,subtotal_minor,total_minor) values('f0283000-0000-4000-8000-000000000001','f0280000-0000-4000-8000-000000000002','f0282000-0000-4000-8000-000000000001','approved','manual_review','KES',0,0);
insert into public.event_memberships(event_id,user_id,status,order_id,ticket_type_id) values('f0282000-0000-4000-8000-000000000001','f0280000-0000-4000-8000-000000000002','confirmed','f0283000-0000-4000-8000-000000000001','f0284000-0000-4000-8000-000000000001');
update public.orders set status='fulfilled',fulfilled_at=now() where id='f0283000-0000-4000-8000-000000000001';
insert into public.event_announcements(event_id,title,body,status,host_workspace_key) values('f0282000-0000-4000-8000-000000000001','Before you arrive','Please arrive fifteen minutes early.','published','arrival');
update public.event_host_workspaces set arrival_info='PRIVATE UNSAVED DRAFT' where event_id='f0282000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','f0280000-0000-4000-8000-000000000001',true);
select public.save_event_host_public_details('f0282000-0000-4000-8000-000000000001','{"display_name":"Amina Host","organisation_name":"[TEST] Women Together","enabled":true}'::jsonb);
select public.save_event_networking('f0282000-0000-4000-8000-000000000001',now()+interval '1 day 15 minutes',now()+interval '1 day 45 minutes',5,60,array['Table 1'],'Hello');
select set_config('request.jwt.claim.sub','f0280000-0000-4000-8000-000000000002',true);
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'guest_name'='Ticket Tester 2','own guest name');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'host_name'='Amina Host','shared Host name');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'organisation_name'='[TEST] Women Together','shared company');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'ticket_type'='[TEST] Free admission','canonical ticket type');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'arrival_info'='Please arrive fifteen minutes early.','only published arrival information');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->'networking'->>'minutes'='5','saved networking schedule included');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'booking_reference'=(select reference from public.orders where id='f0283000-0000-4000-8000-000000000001'),'canonical booking reference');
select pg_temp.ticket_assert((public.get_my_event_ticket('test-ticket-1')->>'manual_code') ~ '^[A-Z0-9]{10}$','ten character backup code');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'qr_payload'=(select qr_payload from public.get_my_event_pass('f0282000-0000-4000-8000-000000000001')),'web and PDF share one credential');
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-2') is null,'other event denied');
select pg_temp.ticket_assert((select count(*)=1 from public.list_my_event_tickets()),'own ticket list');
select pg_temp.ticket_assert((select count(*)=0 from public.list_my_event_tickets(12)),'bounded list offset');
select pg_temp.ticket_assert(pg_temp.ticket_denied($q$select hat_tickets.build_ticket('f0282000-0000-4000-8000-000000000001','f0280000-0000-4000-8000-000000000001')$q$),'private helper inaccessible');
select pg_temp.ticket_assert(pg_temp.ticket_denied($q$select public.get_event_ticket_email('f0283000-0000-4000-8000-000000000001')$q$),'member cannot use delivery RPC');
select set_config('request.jwt.claim.sub','f0280000-0000-4000-8000-000000000003',true);
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1') is null,'unregistered member denied');
select pg_temp.ticket_assert((select count(*)=0 from public.list_my_event_tickets()),'no other member ticket list');
reset role;
update public.event_host_public_details set enabled=false where event_id='f0282000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','f0280000-0000-4000-8000-000000000002',true);
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1')->>'host_name'='Event organising team' and public.get_my_event_ticket('test-ticket-1')->>'organisation_name'='','hidden Host fields not copied');
reset role;
update public.event_host_public_details set enabled=true where event_id='f0282000-0000-4000-8000-000000000001';
do $$begin perform set_config('test.ticket.job',(select id::text from public.notification_jobs where dedupe_key='order-status:f0283000-0000-4000-8000-000000000001:fulfilled'),true);end;$$;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.ticket_assert(public.get_event_ticket_email(current_setting('test.ticket.job')::uuid) is null,'unclaimed job denied');
reset role;
update public.notification_jobs set status='processing',locked_at=now() where id=current_setting('test.ticket.job')::uuid;
set local role service_role;
select pg_temp.ticket_assert(public.get_event_ticket_email(current_setting('test.ticket.job')::uuid)->>'guest_name'='Ticket Tester 2','claimed confirmation gets ticket');
select pg_temp.ticket_assert(public.get_event_ticket_email(current_setting('test.ticket.job')::uuid)=public.get_event_ticket_email(current_setting('test.ticket.job')::uuid),'retry snapshot stable');
reset role;
update public.event_host_public_details set display_name='Changed Host' where event_id='f0282000-0000-4000-8000-000000000001';
set local role service_role;
select pg_temp.ticket_assert(public.get_event_ticket_email(current_setting('test.ticket.job')::uuid)->>'host_name'='Amina Host','retry retains original approved snapshot');
reset role;
update public.notification_jobs set to_email='wrong@test.invalid' where id=current_setting('test.ticket.job')::uuid;
set local role service_role;
select pg_temp.ticket_assert(public.get_event_ticket_email(current_setting('test.ticket.job')::uuid) is null,'changed email recipient denied');
reset role;
update public.notification_jobs set to_email='ticket-2@test.invalid' where id=current_setting('test.ticket.job')::uuid;
update public.orders set status='refund_pending' where id='f0283000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select set_config('request.jwt.claim.sub','f0280000-0000-4000-8000-000000000002',true);
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1') is null,'refund pending cannot download valid pass');
reset role;
update public.orders set status='fulfilled' where id='f0283000-0000-4000-8000-000000000001';
update public.event_checkin_credentials set revoked_at=now() where event_id='f0282000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.ticket_assert(public.get_my_event_ticket('test-ticket-1') is null,'revoked pass denied');
select pg_temp.ticket_assert((select count(*)=0 from public.list_my_event_tickets()),'revoked pass removed from list');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.ticket_assert(public.get_event_ticket_email(current_setting('test.ticket.job')::uuid) is null,'revocation checked even with cached email snapshot');
reset role;
set local role anon;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claims','{"role":"anon"}',true);
select pg_temp.ticket_assert(pg_temp.ticket_denied($q$select public.get_my_event_ticket('test-ticket-1')$q$),'anonymous ticket denied');
select pg_temp.ticket_assert(pg_temp.ticket_denied($q$select public.list_my_event_tickets()$q$),'anonymous list denied');
reset role;
select pg_temp.ticket_assert(not has_schema_privilege('authenticated','hat_tickets','usage'),'no private schema access');
select pg_temp.ticket_assert(not has_function_privilege('authenticated','public.get_event_ticket_email(uuid)','execute'),'no client email RPC grant');
rollback;
